{
  "recipe_id": "idli-batter-01",
  "title": "Idli Batter (2kg batch)",
  "ingredients": [
    {
      "name": "Idli rice (parboiled)",
      "amount": "1000g"
    },
    {
      "name": "Whole white urad dal",
      "amount": "250g"
    },
    {
      "name": "Fenugreek seeds",
      "amount": "10g"
    },
    {
      "name": "Rock salt",
      "amount": "20g"
    },
    {
      "name": "Water for grinding",
      "amount": "~720g"
    }
  ],
  "method": "Wash and soak the rice and the urad dal separately for 4 to 6 hours, with the\nfenugreek seeds in the dal bowl. Grind the dal first with ice-cold water until\nlight, fluffy and tripled in volume — it should hold a soft peak. Grind the\nrice to a fine rava-like texture, slightly grainy between the fingers. Combine\nboth with the rock salt and mix by hand for a full 2 minutes; the warmth of\nyour hand kick-starts the wild fermentation. Ferment 8 to 12 hours at 28–32°C\nuntil doubled and domed. Do not stir the risen batter. Scoop gently into\ngreased idli moulds and steam 12 minutes; rest 2 minutes before unmoulding."
}
